56	func NewHandler(timeline *events.Timeline, log Storage, cursors CursorStore, opts ...Option) *Handler {
57		h := &Handler{timeline: timeline, log: log, cursors: cursors, mux: http.NewServeMux()}
58		for _, opt := range opts {
59			opt(h)
60		}
61		h.mux.HandleFunc("/events", h.events)
62		h.mux.HandleFunc("/alerts/preview", h.previewAlerts)
63		h.mux.HandleFunc("/events/compare", h.compareEvents)
64		h.mux.HandleFunc("/events/page", h.pageEvents)
65		if h.incidents != nil {
66			h.mux.HandleFunc("/incidents", h.incidentsRoot)
67			h.mux.HandleFunc("/incidents/{id}", h.incidentItem)
68			h.mux.HandleFunc("/incidents/{id}/actions", h.incidentActions)
69		}
70		h.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
71			writeError(w, http.StatusNotFound, "not found")
72		})
73		return h
74	}
75	
76	func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
77		h.mux.ServeHTTP(w, r)
78	}
