80	func (h *Handler) unavailable() bool {
81		return h.log.Poisoned()
82	}
83	
84	func (h *Handler) events(w http.ResponseWriter, r *http.Request) {
85		switch r.Method {
86		case http.MethodPost:
87			h.postEvents(w, r)
88		case http.MethodGet:
89			h.getEvents(w, r)
90		default:
91			w.Header().Set("Allow", "GET, POST")
92			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
93		}
94	}
95	
96	func (h *Handler) postEvents(w http.ResponseWriter, r *http.Request) {
97		if h.unavailable() {
98			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
99			return
100		}
101	
102		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
103		if err != nil {
104			writeError(w, http.StatusBadRequest, "invalid JSON body")
105			return
106		}
107	
108		dec := json.NewDecoder(bytes.NewReader(body))
109		dec.DisallowUnknownFields()
110		var input envelope
111		if err := dec.Decode(&input); err != nil {
112			writeError(w, http.StatusBadRequest, "invalid JSON body")
113			return
114		}
115		var extra json.RawMessage
116		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
117			writeError(w, http.StatusBadRequest, "invalid JSON body")
118			return
119		}
120		if len(bytes.TrimSpace(input.Events)) == 0 {
121			writeError(w, http.StatusBadRequest, "events must be a non-empty array")
122			return
123		}
124	
125		batch, err := events.DecodeBatch(input.Events)
126		if err != nil {
127			writeError(w, http.StatusBadRequest, "invalid events array")
128			return
129		}
130		if len(batch) == 0 {
131			writeError(w, http.StatusBadRequest, "events must not be empty")
132			return
133		}
134	
135		result, err := h.timeline.Ingest(batch, h.log.Append)
136		if err != nil {
137			switch {
138			case events.IsValidationError(err):
139				writeError(w, http.StatusBadRequest, err.Error())
140			case events.IsConflictError(err):
141				writeError(w, http.StatusConflict, err.Error())
142			default:
143				writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
144			}
145			return
146		}
147	
148		writeJSON(w, http.StatusOK, map[string]int{
149			"created":  result.Created,
150			"replayed": result.Replayed,
151		})
152	}
153	
154	func (h *Handler) getEvents(w http.ResponseWriter, r *http.Request) {
155		if h.unavailable() {
156			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
157			return
158		}
159	
160		values := r.URL.Query()
161		labels, err := events.ParseLabelConditions(values["label"])
162		if err != nil {
163			writeError(w, http.StatusBadRequest, err.Error())
164			return
165		}
166		query := events.Query{
167			Service:  values.Get("service"),
168			Severity: values.Get("severity"),
169			Labels:   labels,
170		}
171		if raw := values.Get("since"); raw != "" {
172			parsed, err := time.Parse(time.RFC3339Nano, raw)
173			if err != nil {
174				writeError(w, http.StatusBadRequest, "since must be an RFC3339Nano timestamp")
175				return
176			}
177			query.Since = parsed
178		}
179		if raw := values.Get("until"); raw != "" {
180			parsed, err := time.Parse(time.RFC3339Nano, raw)
181			if err != nil {
182				writeError(w, http.StatusBadRequest, "until must be an RFC3339Nano timestamp")
183				return
184			}
185			query.Until = parsed
186		}
187		if !query.Since.IsZero() && !query.Until.IsZero() && query.Since.After(query.Until) {
188			writeError(w, http.StatusBadRequest, "since must not be after until")
189			return
190		}
191	
192		found := h.timeline.Query(query)
193		writeEvents(w, found)
194	}
