207	func writeEvents(w http.ResponseWriter, found []events.Event) {
208		w.Header().Set("Content-Type", "application/json")
209		w.WriteHeader(http.StatusOK)
210		if len(found) == 0 {
211			_, _ = w.Write([]byte("[]\n"))
212			return
213		}
214		if err := json.NewEncoder(w).Encode(eventsToDTOs(found)); err != nil {
215			return
216		}
217	}
