671		postEvents(t, p2, `{"events":[`+
672			`{"id":"e1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:05Z","labels":{"env":"prod"}},`+
673			`{"id":"e2","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:01:05Z","labels":{"env":"prod"}},`+
674			`{"id":"e3","service":"api","severity":"info","message":"m","at":"2026-10-01T10:00:05Z"}]}`)
675		_, replayed := httpDo(t, http.MethodPost, "http://"+p2.addr+"/alerts/preview", body)
676		if !bytes.Equal(before, replayed) {
677			t.Fatalf("replaying events changed the preview:\n%s\n%s", before, replayed)
678		}
679		p2.signal(t, syscall.SIGTERM)
680		p2.waitExit(t, 0)
681	}
682	
683	func TestServePageSnapshotStableAcrossRestart(t *testing.T) {
684		dataDir := t.TempDir()
685		p := startServer(t, dataDir)
686		postEvents(t, p, `{"events":[
687			{"id":"e1","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"},
688			{"id":"e2","service":"s","severity":"info","message":"m","at":"2026-10-01T09:02:00Z"}
689		]}`)
690	
691		// First page, limit 1.
692		_, out := pageGet(t, p, "?limit=1")
693		if out.NextCursor == nil {
694			t.Fatal("expected a next_cursor")
695		}
696	
697		// Restart, then ingest a new event with an earlier time.
698		p.signal(t, syscall.SIGKILL)
699		p.waitExit(t, -1)
700		waitTCPPortClosed(t, p.addr)
701		p2 := startServer(t, dataDir)
702		postEvents(t, p2, `{"events":[{"id":"e0","service":"s","severity":"info","message":"m","at":"2026-10-01T08:00:00Z"}]}`)
703	
704		// The old cursor must continue the old snapshot, not see e0.
705		_, out = pageGet(t, p2, "?limit=1&cursor="+*out.NextCursor)
706		if len(out.Events) != 1 || out.Events[0]["id"] != "e2" {
707			t.Fatalf("old cursor must not see post-restart event: %v", out.Events)
708		}
