package metrics

import (
	"errors"
	"math"
	"sort"
	"strings"
	"time"
)

// Aggregation limits: at most this many segments cover one query window, and
// the response must not contain more than this many series-segment pairs.
// Requests beyond either bound are rejected rather than truncated.
const (
	MaxAggregateSegments       = 10000
	MaxAggregateSeriesSegments = 100000
)

// AggregateQuery selects samples by exact metric name, optional exact service,
// and the same label conditions event queries use, over the half-open window
// [Since, Until), split from Since into intervals of Step.
type AggregateQuery struct {
	Name    string
	Service string
	Since   time.Time
	Until   time.Time
	Step    time.Duration
	Labels  map[string]string
}

// AggregateSegment is one aligned slice of one series: the UTC boundaries,
// how many samples fall in it, and the cumulative-counter delta attributed to
// it. Segments without samples carry a zero count and delta.
type AggregateSegment struct {
	Start time.Time
	End   time.Time
	Count int
	Delta float64
}

// AggregateSeries is one matching series' complete segment set. Labels is nil
// when the series has none.
type AggregateSeries struct {
	Service string
	Labels  map[string]string
	Segments []AggregateSegment
}

// Query problems aggregation can hit. The HTTP layer maps each to a status.
var (
	// ErrAggregateStep reports a non-positive step.
	ErrAggregateStep = errors.New("aggregate step must be positive")
	// ErrAggregateWindow reports a start not strictly before its end.
	ErrAggregateWindow = errors.New("aggregate window must start before it ends")
	// ErrTooManySegments reports a window needing more than
	// MaxAggregateSegments segments.
	ErrTooManySegments = errors.New("aggregate window requires too many segments")
	// ErrTooManySeriesSegments reports a response holding more than
	// MaxAggregateSeriesSegments series-segment pairs.
	ErrTooManySeriesSegments = errors.New("aggregate covers too many series segments")
	// ErrDeltaNotFinite reports increments whose sum overflows to a
	// non-finite value; the whole query fails rather than returning Inf/NaN.
	ErrDeltaNotFinite = errors.New("aggregate delta total is not a finite number")
)

// Aggregate computes per-series sample counts and cumulative deltas over the
// query window using a single read of the store, so every series and segment
// reflects one committed snapshot. Late arrivals are bucketed by their own
// sample time, so an unchanged dataset always yields the same result
// regardless of ingestion order.
func (s *Store) Aggregate(query AggregateQuery) ([]AggregateSeries, error) {
	segments, err := ValidateAggregateQuery(query)
	if err != nil {
		return nil, err
	}

	name := strings.TrimSpace(query.Name)
	service := strings.TrimSpace(query.Service)

	s.mu.RLock()
	defer s.mu.RUnlock()

	// Select the matching series that actually have a sample in the
	// half-open window, in a stable order (service, then full label set).
	keys := make([]seriesKey, 0, len(s.series))
	for key, state := range s.series {
		if key.name != name {
			continue
		}
		if service != "" && key.service != service {
			continue
		}
		if !seriesLabelsMatch(state, query.Labels) {
			continue
		}
		if !state.hasPointBetween(query.Since, query.Until) {
			continue
		}
		keys = append(keys, key)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].service != keys[j].service {
			return keys[i].service < keys[j].service
		}
		return keys[i].labels < keys[j].labels
	})

	if len(keys)*len(segments) > MaxAggregateSeriesSegments {
		return nil, ErrTooManySeriesSegments
	}

	out := make([]AggregateSeries, 0, len(keys))
	for _, key := range keys {
		state := s.series[key]
		seriesSegs := append([]AggregateSegment(nil), segments...)
		if err := fillSeries(seriesSegs, state.points, query); err != nil {
			return nil, err
		}
		out = append(out, AggregateSeries{
			Service:  key.service,
			Labels:   s.byIDLabels(key, state),
			Segments: seriesSegs,
		})
	}
	return out, nil
}

// byIDLabels recovers the concrete label map for a series; all points of a
// series share it, so the first point's sample carries it.
func (s *Store) byIDLabels(key seriesKey, state *seriesState) map[string]string {
	for _, p := range state.points {
		if sample, ok := s.byID[p.id]; ok && len(sample.Labels) > 0 {
			return sample.Labels
		}
	}
	return nil
}

// ValidateAggregateQuery enforces a positive step, a strictly increasing
// half-open window, and the segment bound, then returns the segment skeleton
// (UTC-relative boundaries are the caller's job at rendering time).
func ValidateAggregateQuery(query AggregateQuery) ([]AggregateSegment, error) {
	if query.Step <= 0 {
		return nil, ErrAggregateStep
	}
	length := query.Until.Sub(query.Since)
	if length <= 0 {
		return nil, ErrAggregateWindow
	}
	count := int64(length / query.Step)
	if length%query.Step != 0 {
		count++
	}
	if count > MaxAggregateSegments {
		return nil, ErrTooManySegments
	}

	out := make([]AggregateSegment, count)
	for i := range out {
		start := query.Since.Add(query.Step * time.Duration(i))
		end := start.Add(query.Step)
		if end.After(query.Until) {
			end = query.Until
		}
		out[i] = AggregateSegment{Start: start, End: end}
	}
	return out, nil
}

// seriesLabelsMatch checks the (already shared) label set of one series
// against every condition. A series missing a conditioned label never
// matches; comparison is case-sensitive.
func seriesLabelsMatch(state *seriesState, conditions map[string]string) bool {
	if len(conditions) == 0 {
		return true
	}
	// A series' label set is constant across its points; inspect the labels
	// stored on the first point's sample via the state's recorded value is not
	// possible here, so the caller passes a state whose points' ids resolve in
	// the store. Instead the label set is compared through the key by the
	// caller-supplied conditions using a small helper below.
	return labelsOnStateMatch(state, conditions)
}

// hasPointBetween reports whether any point falls in [since, until).
func (st *seriesState) hasPointBetween(since, until time.Time) bool {
	idx := sort.Search(len(st.points), func(i int) bool {
		return !st.points[i].at.Before(since)
	})
	return idx < len(st.points) && st.points[idx].at.Before(until)
}

// fillSeries counts samples per segment and attributes cumulative deltas.
// The nearest sample strictly before the window start acts as the first
// in-window sample's predecessor; a sample with no predecessor anywhere
// contributes no delta. A value that does not move backwards contributes the
// difference; a backwards move is a counter reset and contributes the current
// value. Every delta lands in the segment containing the later sample; the
// sample at the window end never participates.
func fillSeries(segments []AggregateSegment, points []point, query AggregateQuery) error {
	step := query.Step

	// First point at or after the window start.
	first := sort.Search(len(points), func(i int) bool {
		return !points[i].at.Before(query.Since)
	})

	var prevValue float64
	hasPrev := false
	if first > 0 {
		prevValue = points[first-1].value
		hasPrev = true
	}

	for _, p := range points[first:] {
		if !p.at.Before(query.Until) {
			break // at == until and anything later is excluded
		}
		idx := int(p.at.Sub(query.Since) / step)
		if idx >= len(segments) {
			idx = len(segments) - 1 // defensive; excluded end keeps this in range
		}
		segments[idx].Count++

		var delta float64
		if hasPrev {
			if p.value >= prevValue {
				delta = p.value - prevValue
			} else {
				delta = p.value // counter reset
			}
			segments[idx].Delta += delta
			if !isFinite(segments[idx].Delta) {
				return ErrDeltaNotFinite
			}
		}
		prevValue = p.value
		hasPrev = true
	}
	return nil
}

func isFinite(v float64) bool {
	return !math.IsNaN(v) && !math.IsInf(v, 0)
}

// Package metrics holds cumulative metric samples: their normalized content,
// batch ingestion with de-duplication, and the delta aggregation over aligned
// segments. Sample ids are independent of event ids.
package metrics

import (
	"errors"
	"maps"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
)

// ValidationError reports that a sample failed normalization (or, during
// aggregation, that a query was invalid).
type ValidationError struct{ Reason string }

func (e *ValidationError) Error() string { return e.Reason }

// IsValidationError reports whether err is a metrics validation failure.
func IsValidationError(err error) bool {
	var target *ValidationError
	return errors.As(err, &target)
}

// ConflictError reports an id clash with different content, a repeated id in
// one batch, or a series/time clash between different ids.
type ConflictError struct{ Reason string }

func (e *ConflictError) Error() string { return e.Reason }

// IsConflictError reports whether err is a metrics conflict.
func IsConflictError(err error) bool {
	var target *ConflictError
	return errors.As(err, &target)
}

// Sample is one normalized cumulative counter reading. Labels carries the
// optional trimmed label set and is nil when the sample has none.
type Sample struct {
	ID      string
	Service string
	Name    string
	At      time.Time
	Value   float64
	Labels  map[string]string
}

// Normalize applies the ingestion rules: trim surrounding whitespace from id,
// service, and metric name (their case is kept) and require each non-empty
// afterwards; require a non-zero instant; require a non-negative, finite
// value; and trim/validate labels with the same rules events use.
func Normalize(s Sample) (Sample, error) {
	s.ID = strings.TrimSpace(s.ID)
	s.Service = strings.TrimSpace(s.Service)
	s.Name = strings.TrimSpace(s.Name)
	if s.ID == "" || s.Service == "" || s.Name == "" || s.At.IsZero() {
		return Sample{}, &ValidationError{Reason: "sample id, service, name, and timestamp are required"}
	}
	if !finiteNonNegative(s.Value) {
		return Sample{}, &ValidationError{Reason: "value must be a non-negative, finite JSON number"}
	}
	labels, err := events.NormalizeLabels(s.Labels)
	if err != nil {
		return Sample{}, &ValidationError{Reason: err.Error()}
	}
	s.Labels = labels
	return s, nil
}

// finiteNonNegative rejects NaN, infinities (which JSON cannot carry anyway),
// and negative readings.
func finiteNonNegative(v float64) bool {
	return v == v && v < 1.0/0.0 && -v < 1.0/0.0 && v >= 0
}

// seriesKey identifies one time series: a metric name within a service plus
// the complete label set. Names are compared case-sensitively after trimming.
type seriesKey struct {
	service string
	name    string
	labels  string
}

// BeforeCommit persists a batch of brand-new samples. It runs while the store
// lock is held and before the batch becomes visible, so a successful return
// guarantees the batch is durable and committed atomically.
type BeforeCommit func(persisted []Sample) error

// Store is a concurrency-safe set of metric samples grouped into series. It
// accepts whole batches and reports retries of already-stored samples.
type Store struct {
	mu     sync.RWMutex
	byID   map[string]Sample
	series map[seriesKey]*seriesState
}

// NewStore returns an empty store.
func NewStore() *Store {
	return &Store{
		byID:   make(map[string]Sample),
		series: make(map[seriesKey]*seriesState),
	}
}

// IngestResult counts how a batch was applied: Created samples are new,
// Replayed samples matched an existing sample with the same id and content.
type IngestResult struct {
	Created   int
	Replayed  int
}

// Ingest normalizes and validates every sample first, then checks the whole
// batch against stored samples and itself. Validation failures produce a
// ValidationError; duplicate ids with differing content, a repeated id within
// the batch, or a (series, time) clash between different ids produce a
// ConflictError. Nothing is stored when an error is returned.
//
// New samples are passed to beforeCommit for durable storage; only after it
// succeeds does the batch become visible, so concurrent readers see either the
// complete batch or none of it, and concurrent batches serialize so the whole
// batch either commits or fails.
func (s *Store) Ingest(batch []Sample, beforeCommit BeforeCommit) (IngestResult, error) {
	normalized := make([]Sample, len(batch))
	for i, sample := range batch {
		norm, err := Normalize(sample)
		if err != nil {
			return IngestResult{}, err
		}
		normalized[i] = norm
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	pendingID := make(map[string]struct{}, len(normalized))
	pendingPoint := make(map[seriesKey]map[int64]string, len(normalized))
	var created []Sample
	var result IngestResult
	for _, sample := range normalized {
		if _, repeated := pendingID[sample.ID]; repeated {
			return IngestResult{}, &ConflictError{Reason: "sample id repeats within batch"}
		}
		pendingID[sample.ID] = struct{}{}

		key := keyFor(sample)
		if existing, ok := s.byID[sample.ID]; ok {
			if !sameContent(existing, sample) {
				return IngestResult{}, &ConflictError{Reason: "sample id already exists with different content"}
			}
			// An id retry must never mask another id's point.
			if owner := s.series[key].pointOwner(sample.At); owner != "" && owner != sample.ID {
				return IngestResult{}, &ConflictError{
					Reason: "sample collides with a different sample of the same series at the same time"}
			}
			result.Replayed++
			continue
		}

		// A brand-new id must not claim a (series, time) point already stored
		// under another id.
		if owner := s.series[key].pointOwner(sample.At); owner != "" {
			return IngestResult{}, &ConflictError{
				Reason: "sample collides with a different sample of the same series at the same time"}
		}
		// Nor one introduced earlier in this same batch.
		if owners := pendingPoint[key]; owners != nil {
			if owner, dup := owners[sample.At.UnixNano()]; dup && owner != sample.ID {
				return IngestResult{}, &ConflictError{
					Reason: "sample collides with a different sample of the same series at the same time"}
			}
		}
		created = append(created, sample)
		result.Created++
		if pendingPoint[key] == nil {
			pendingPoint[key] = make(map[int64]string)
		}
		pendingPoint[key][sample.At.UnixNano()] = sample.ID
	}

	if len(created) > 0 {
		if beforeCommit != nil {
			if err := beforeCommit(created); err != nil {
				return IngestResult{}, err
			}
		}
		for _, sample := range created {
			s.byID[sample.ID] = sample
			key := keyFor(sample)
			state := s.series[key]
			if state == nil {
				state = &seriesState{labels: sample.Labels}
				s.series[key] = state
			}
			state.add(sample)
		}
	}
	return result, nil
}

// Load inserts samples recovered from durable storage during startup. Every
// sample must already be normalized; a contradictory record is reported as a
// conflict so the caller can fail rather than mutate data.
func (s *Store) Load(sample Sample) error {
	if _, err := Normalize(sample); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	key := keyFor(sample)
	if existing, ok := s.byID[sample.ID]; ok {
		if !sameContent(existing, sample) {
			return &ConflictError{Reason: "sample id already exists with different content"}
		}
		return nil
	}
	if owner := s.series[key].pointOwner(sample.At); owner != "" {
		return &ConflictError{Reason: "sample collides with a different sample of the same series at the same time"}
	}
	s.byID[sample.ID] = sample
	state := s.series[key]
