		}
	}
}

func TestMarshalDecodeRoundTrip(t *testing.T) {
	original := []Sample{
		{ID: "a", Service: "gw", Name: "req", At: at(10), Value: 1.0},
		{ID: "b", Service: "gw", Name: "req", At: at(11), Value: 2, Labels: map[string]string{"env": "prod"}},
