	}
}

func q(since, until int64, stepSec int64, name string) AggregateQuery {
	return AggregateQuery{
		Name:  name,
		Since: at(since),
		Until: at(until),
		Step:  time.Duration(stepSec) * time.Second,
	}
}

func TestAggregateDeltasResetsAndPredecessor(t *testing.T) {
	s := NewStore()
