// labelsKey renders a label set as a collision-free canonical string so two
// maps with the same complete set share a series regardless of iteration
// order. Name and value are each length-prefixed, which keeps values
// containing '=' or ';' from ever aliasing another set.
func labelsKey(labels map[string]string) string {
	if len(labels) == 0 {
		return ""
	}
	keys := make([]string, 0, len(labels))
	for name := range labels {
		keys = append(keys, name)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, name := range keys {
		value := labels[name]
		b.WriteString(strconv.Itoa(utf8.RuneCountInString(name)))
		b.WriteByte(':')
		b.WriteString(name)
		b.WriteByte(',')
		b.WriteString(strconv.Itoa(utf8.RuneCountInString(value)))
		b.WriteByte(':')
		b.WriteString(value)
		b.WriteByte(';')
	}
	return b.String()
}

